@Injectable()
export class TournamentFootballRosterService {
…
  async updateFootballRoster(
…
  ) {
…
    this.tournamentRealtimeService.broadcastRegistrationChanged(tournamentId, {
      participantId,
      divisionId: participant.tournamentDivisionId,
      action: 'ROSTER_UPDATED',
    });
    return updated;
  }
  async assignReservedSlot(
    tournamentId: string,
    userEmailOrPhone: string,
    teamName: string,
    userId: string,
    systemRoles: string[] = [],
    partnerEmailOrPhone?: string,
    divisionId?: string,
  ) {
    const tournament = await this.tournamentsRepository.findById(tournamentId);
    if (!tournament) throw new NotFoundException('Giải đấu không tồn tại');

    const isAuthorized = await this.tournamentAccessService.isManager(tournament, userId, systemRoles);
    if (!isAuthorized) {
      throw new ForbiddenException('Bạn không có quyền cấp đặc cách');
    }

    if (tournament.status !== 'REGISTRATION_OPEN') {
      throw new BadRequestException(
        'Giải đấu đã chốt danh sách, không thể gán slot giữ chỗ.',
      );
    }

    const foundUser =
      await this.tournamentsRepository.findUserByEmailOrPhone(userEmailOrPhone);
    if (!foundUser) {
      throw new NotFoundException(
        'Không tìm thấy tài khoản Sporto cho người chơi thứ nhất',
      );
    }

    let foundPartnerId: string | undefined = undefined;
    if (partnerEmailOrPhone) {
      const foundPartner =
        await this.tournamentsRepository.findUserByEmailOrPhone(
          partnerEmailOrPhone,
        );
      if (!foundPartner) {
        throw new NotFoundException(
          'Không tìm thấy tài khoản Sporto cho đồng đội (người thứ 2)',
        );
      }
      if (foundPartner.id === foundUser.id) {
        throw new BadRequestException(
          'Tài khoản đồng đội phải khác tài khoản người chơi thứ nhất',
        );
      }
      foundPartnerId = foundPartner.id;
    }

    const assignedParticipant =
      await this.tournamentsRepository.assignReservedSlot(
        tournamentId,
        foundUser.id,
        teamName,
        foundPartnerId,
        divisionId,
      );

    try {
      await this.notificationsService.sendNotification(
        buildReservedSlotAssignedNotification({
          receiverId: foundUser.id,
          tournamentId,
          tournamentName: tournament.name,
          divisionId: assignedParticipant.tournamentDivisionId,
        }),
      );

      if (foundPartnerId) {
        await this.notificationsService.sendNotification(
          buildReservedSlotAssignedNotification({
            receiverId: foundPartnerId,
            tournamentId,
            tournamentName: tournament.name,
            divisionId: assignedParticipant.tournamentDivisionId,
          }),
        );
      }
    } catch (err) {
      console.error('Failed to send reserved slot notification:', err);
    }

    return assignedParticipant;
  }
}

  async findUserByEmailOrPhone(emailOrPhone: string) {
    const [user] = await this.db
…
      .where(
        or(
…
          eq(schema.profiles.phoneNumber, emailOrPhone),
        ),
      )
      .limit(1);
    return user;
  }
  async assignReservedSlot(
    tournamentId: string,
    userId: string,
    teamName: string,
    partnerId?: string,
    divisionId?: string,
  ) {
    return await this.db.transaction(async (tx) => {
      const tournament = await tx
        .select()
        .from(schema.tournaments)
        .where(eq(schema.tournaments.id, tournamentId))
        .limit(1)
        .then((res) => res[0]);

      if (!tournament) throw new BadRequestException('Giải đấu không tồn tại');

      let divisionMatchType = tournament.matchType;
      if (divisionId) {
        const division = await tx
          .select()
          .from(schema.tournamentDivisions)
          .where(
            and(
              eq(schema.tournamentDivisions.id, divisionId),
              eq(schema.tournamentDivisions.tournamentId, tournamentId),
            ),
          )
          .limit(1)
          .then((res) => res[0]);

        if (!division) {
          throw new BadRequestException('Hình thức thi đấu không hợp lệ.');
        }

        divisionMatchType = division.matchType;
      }

      const isDoubles =
        divisionMatchType === 'DOUBLES' ||
        divisionMatchType === 'MIXED_DOUBLES';
      const teamStatus = isDoubles
        ? partnerId
          ? 'COMPLETE'
          : 'PENDING_PARTNER'
        : 'COMPLETE';

      const [participant] = await tx
        .insert(schema.tournamentParticipants)
        .values({
          tournamentId,
          tournamentDivisionId: divisionId ?? null,
          registeredBy: userId,
          teamName: teamName || 'Đội khách mời',
          isPaid: true,
          entryFeeAtRegistration: (
            await this.tournamentPaymentRepository.resolveDivisionEntryFee(
              tx,
              tournament,
              divisionId,
            )
          ).toFixed(2),
          isWildcard: true,
          teamStatus,
        })
        .returning();

      await tx.insert(schema.tournamentRosters).values({
        participantId: participant.id,
        userId: userId,
        role: 'MAIN',
      });

      if (isDoubles && partnerId) {
        await tx.insert(schema.tournamentRosters).values({
          participantId: participant.id,
          userId: partnerId,
          role: 'MAIN',
        });
      }
…
    });
  }

export const tournamentParticipants = pgTable('tournament_participants', {
  id: uuid('id').primaryKey().defaultRandom(),
  tournamentId: uuid('tournament_id')
    .references(() => tournaments.id, { onDelete: 'cascade' })
    .notNull(),
  tournamentDivisionId: uuid('tournament_division_id').references(
    () => tournamentDivisions.id,
    { onDelete: 'cascade' },
  ),
  groupId: uuid('group_id').references(() => tournamentGroups.id, {
    onDelete: 'set null',
  }),
  registeredBy: uuid('registered_by')
    .references(() => users.id, { onDelete: 'restrict' })
    .notNull(),
  teamName: varchar('team_name', { length: 255 }).notNull(),
  // FK is applied by the standalone migration to avoid a runtime schema import cycle.
  footballTeamId: uuid('football_team_id'),
  footballTeamLogoUrl: varchar('football_team_logo_url', { length: 1000 }),
  seed: integer('seed'),
  points: integer('points').default(0).notNull(),
  rankingConsent: boolean('ranking_consent').default(false).notNull(),
  customResponses: jsonb('custom_responses'),
  isPaid: boolean('is_paid').default(false).notNull(),
  // Organizer's own day-of-event mark. Carries no meaning anywhere else: it does
  // not gate roster approval, does not affect ELO, and does not block playing.
  isPresent: boolean('is_present').default(false).notNull(),
  // Effective registration fee captured when this participant is created.
  // This is distinct from isPaid: zero means free at registration, while
  // isPaid=true after a paid flow means the payment was captured.
  entryFeeAtRegistration: numeric('entry_fee_at_registration', {
    precision: 12,
    scale: 2,
  }).default('0.00').notNull(),
  teamInviteToken: varchar('team_invite_token', { length: 50 }).unique(),
  teamStatus: varchar('team_status', { length: 50 }).default('PENDING').notNull(),
  partnerUserId: uuid('partner_user_id').references(() => users.id, { onDelete: 'restrict' }),
  partnerInviteExpiresAt: timestamp('partner_invite_expires_at', { withTimezone: true }),
  isMock: boolean('is_mock').default(false).notNull(),
  isWildcard: boolean('is_wildcard').default(false).notNull(),
  registeredAt: timestamp('registered_at', { withTimezone: true })
    .defaultNow()
    .notNull(),
  rosterLockedAt: timestamp('roster_locked_at', { withTimezone: true }),
}, (table) => ({
  idxParticipantsTournamentStatus: index('idx_participants_tournament_status').on(
    table.tournamentId,
    table.teamStatus,
  ),
  idxParticipantsTournamentId: index('idx_participants_tournament_id').on(
    table.tournamentId,
  ),
  idxParticipantsDivisionStatus: index(
    'idx_participants_division_status',
  ).on(table.tournamentDivisionId, table.teamStatus),
}));

export const tournamentRosters = pgTable('tournament_rosters', {
  id: uuid('id').primaryKey().defaultRandom(),
  participantId: uuid('participant_id')
    .references(() => tournamentParticipants.id, { onDelete: 'cascade' })
    .notNull(),
…
}, (table) => ({
…
}));

